#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""engine/esq_tables.h: the numbers the engine does not compute on the FM-1 (integers only there).

    tools/gen_tables.py

What is measured or documented and what is this port's estimate is said at each table; README.md has the list."""
import math, sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from esq_data import FS

ROOT = Path(__file__).resolve().parent.parent
TICK = 32                                           # native frames per control tick
TICK_HZ = FS / TICK
OUT_HZ = 44100
FIR_TAPS, FIR_PHASES = 16, 256


def i0(x):
    s, t, k = 1.0, 1.0, 1
    while t > 1e-12 * s:
        t *= (x / (2.0 * k)) ** 2
        s += t
        k += 1
    return s


def rows(vals, per, fmt="{}"):
    out = []
    for k in range(0, len(vals), per):
        out.append("    " + ", ".join(fmt.format(v) for v in vals[k:k + per]) + ",")
    return out


def main():
    L = ["/* SPDX-License-Identifier: GPL-3.0-only */", "/* Generated by tools/gen_tables.py. */",
         "#ifndef ESQ_TABLES_H", "#define ESQ_TABLES_H", "#include <stdint.h>", "",
         f"#define ESQ_TICK {TICK}u                      /* native frames per control tick ({TICK_HZ:.1f} Hz) */",
         f"#define ESQ_FIR_TAPS {FIR_TAPS}", f"#define ESQ_FIR_PHASES {FIR_PHASES}",
         # 44100 Hz out of 38461.54: a native frame every 5000/5733 of an output frame
         f"#define ESQ_STEP_Q32 {round(FS / OUT_HZ * 2 ** 32)}u   /* native frames per output frame, Q32 */", ""]

    # the DOC's frequency register for a resolution-1 table of one cycle: f = FS * FR / 2^18. One octave
    # (MIDI 120..132) in steps of 1/32 semitone, times 256; lower octaves shift right.
    fr = [round(440.0 * 2 ** 18 / FS * 2.0 ** ((120 + i / 32.0 - 69) / 12.0) * 256) for i in range(385)]
    L += ["/* FR x 256 for MIDI 120 + i/32 (the DOC: f = FS * FR / 2^(17 + res), FS = 8 MHz / 8 / 26) */",
          "static const uint32_t ESQ_FR[385] = {", *rows(fr, 8), "};", ""]

    # envelope times: the manual's chart (T=3 .02 s, doubling every six steps up to 20.48 s at 63)
    ticks = [max(2, round(0.01 * 2.0 ** ((t + 3) / 6.0) * TICK_HZ)) for t in range(64)]
    ticks[0] = 3                                    # "0.00": as short as a tick or two
    L += ["/* control ticks for an envelope TIME 0..63: the manual's chart, 0.01 s * 2^((T + 3) / 6) */",
          "static const uint16_t ESQ_ENV_TICKS[64] = {", *rows(ticks, 12), "};", ""]

    # the CEM3379's cutoff from the 8-bit DAC.
    # The slope is the circuit's (data sheet and the ESQ-1's schematic, buchty.net): Gm = 200 umho * exp(Vfc / 28.5 mV)
    # into 33 nF, Vfc from the DAC's 0..5 V through 20K (R107), 1K (R106) to ground and 56K (R108) to -5 V:
    # 0.918 mV a DAC step, 21.6 steps an octave. Those parts alone would put DAC 0 at 51 Hz (964.6 Hz at 0 V,
    # -83.6 mV at DAC 0), but the ESQ-1's OS tunes each voice's filter at power-on (the schematic's T line to a
    # comparator), and where it puts the scale is measured: in recordings of an ESQ-1's factory programs
    # (synthmania.com/esq-1.htm) SHAKER's noise (FREQ 90, no keyboard, no modulation) knees at 7 kHz, KALMBA
    # (FREQ 67, RES 16) rings near 1.5 kHz and SNAPS1 (FREQ 21 + velocity * 63, RES 31) up to 5 kHz: 21 Hz at
    # DAC 0. (MAME's esq1.cpp has 5 Hz.)
    # For the engine: the one-pole's G = g / (1 + g), g = tan(pi f / FS), Q28, held under the native Nyquist.
    g = []
    for d in range(257):
        f = 21.0 * math.exp(0.046823 * 5.0 * d / 255.0 / 0.0285)
        f = min(f, 0.45 * FS)
        t_ = math.tan(math.pi * f / FS)
        g.append(round(t_ / (1 + t_) * 2 ** 28))
    L += ["/* the filter's one-pole coefficient G (Q28) for the cutoff DAC 0..255 (and one more to interpolate to) */",
          "static const uint32_t ESQ_FC_G[257] = {", *rows(g, 8), "};", ""]

    # the CEM3379's VCA (MAME's reading of the data sheet): exponential under 0.2 V (-100..-20 dB), linear above
    amp = []
    for d in range(256):
        v = d * 5.0 / 255.0
        a = 10 ** (-5 + 20 * v) if v < 0.2 else v * 0.1875 + 0.0625
        amp.append(round(a * 0.5 * 32767))
    amp[0] = 0
    # (half of Q15 at the top: the mix's level. One oscillator wide open is then an eighth of full scale in the
    # middle of the pan; four keys of the loudest programs struck as hard as can be stay under the mix's knee, and
    # all eight voices stay under its ceiling)
    L += ["/* the final VCA's gain for its DAC 0..255: -100..-20 dB under 0.2 V, linear above; 16384 at the top */",
          "static const uint16_t ESQ_AMP[256] = {", *rows(amp, 12), "};", ""]

    # the control voltages' RCs after the sample-and-holds (the schematic): the VCA's 20K and 0.1 uF (2 ms), the
    # pan's 47K and 0.1 uF (4.7 ms); the cutoff and the resonance go to their pins direct. As a step a tick, Q15.
    L += [f"#define ESQ_VCA_SMOOTH {round((1 - math.exp(-1 / TICK_HZ / 2.0e-3)) * 32768)}   /* 2 ms */",
          f"#define ESQ_PAN_SMOOTH {round((1 - math.exp(-1 / TICK_HZ / 4.7e-3)) * 32768)}   /* 4.7 ms */", ""]
    # the output stage's two lowpasses (the schematic: 5.1K with 1500 pF at the summing amplifier, 47K with 220 pF
    # at the output's): 20.8 kHz and 15.4 kHz, at 44100 Hz, G = g / (1 + g) in Q15
    for name, r, c in (("ESQ_OUT_G1", 5.1e3, 1500e-12), ("ESQ_OUT_G2", 47e3, 220e-12)):
        fc = 1 / (2 * math.pi * r * c)
        tg = math.tan(math.pi * fc / OUT_HZ)
        L.append(f"#define {name} {round(tg / (1 + tg) * 32768)}   /* {fc:.0f} Hz */")
    L.append("")

    # the CEM3379's pan: the two gains are complementary, half each at 2.5 V, straight between 1 V and 3.5 V and
    # exponential beyond, 100 dB down at the ends (the data sheet; the slope as MAME's esq1.cpp takes it: -30 dB at
    # 1 V). The recordings agree: a full pan LFO moves the balance about 0.4 either way, not 0.25.
    def pan_gain(v):
        if v > 2.5:
            return 1.0 - pan_gain(5.0 - v)
        return 10 ** (-5 + 3.5 * v) if v < 1.0 else 0.0316 + (v - 1.0) * (0.5 - 0.0316) / 1.5
    pan = [round(pan_gain(5.0 * d / 255.0) * 32768) for d in range(256)]
    L += ["/* the right output's share of the gain (Q15) for the pan DAC 0..255; the left has the rest */",
          "static const uint16_t ESQ_PAN[256] = {", *rows(pan, 12), "};", ""]

    # estimates of this port (no measurement of an ESQ-1 behind them)
    vel2 = [round(63 * (v / 127.0) ** 3) for v in range(128)]
    L += ["/* VEL2 / the envelopes' exponential velocity: 63 * (v / 127)^3 (an estimate of the manual's curve) */",
          "static const uint8_t ESQ_VEL2[128] = {", *rows(vel2, 16), "};", ""]
    # LFO rates, measured (tests/recordings.py): eleven of the ESQ-1's factory programs pan with a triangle LFO, and
    # in recordings of them (synthmania.com/esq-1.htm) the stereo balance turns at 0.25 Hz for FREQ 6, 0.77 for 8,
    # 1.3 for 10, 1.84 for 12, 2.76 for 16 (ORGAN1's tremolo too) and 3.8 for 18; ECHO#'s echoes, a sawtooth at
    # FREQ 15, come at 2.9 Hz. The line through them: 0.286 Hz a step from 5.3. Under FREQ 6 and over 18 nothing
    # is measured: the line on upward (4.8 Hz at 22, the factory programs' vibrato), a slower one down to FREQ 0.
    lfo = [round((0.286 * (v - 5.3) if v >= 6 else 0.033 * (v + 1)) / TICK_HZ * 2 ** 32) for v in range(64)]
    L += ["/* an LFO's phase step per tick for FREQ 0..63: 0.286 * (FREQ - 5.3) Hz from 6 up (measured), 0.033 * (FREQ + 1) under */",
          "static const uint32_t ESQ_LFO_INC[64] = {", *rows(lfo, 8), "};", ""]
    dly = [round(0.7 * d / TICK_HZ * 65536) for d in range(64)]
    L += ["/* an LFO's DELAY 0..63 as levels per tick, Q16: 0.7 * DELAY levels a second, 0 stays at L1 (an estimate) */",
          "static const uint32_t ESQ_LFO_RAMP[64] = {", *rows(dly, 8), "};", ""]
    gl = [0] + [round(600.0 * 2.0 ** (-v / 7.0) / TICK_HZ * 65536) for v in range(1, 64)]
    L += ["/* GLIDE 0..63 as semitones per tick, Q16: 600 * 2^(-GLIDE / 7) semitones a second (an estimate) */",
          "static const uint32_t ESQ_GLIDE[64] = {", *rows(gl, 8), "};", ""]

    # 38461.5 Hz -> 44100 Hz: a Kaiser-windowed sinc cut at the native Nyquist, 16 taps in 256 phases, Q14
    beta = 6.0
    fir = []
    for p in range(FIR_PHASES):
        fr_ = p / FIR_PHASES
        row = []
        for k in range(FIR_TAPS):
            t = k - (FIR_TAPS // 2 - 1) - fr_
            s = 1.0 if abs(t) < 1e-12 else math.sin(math.pi * t) / (math.pi * t)
            x = t / (FIR_TAPS / 2)
            w = i0(beta * math.sqrt(max(0.0, 1 - x * x))) / i0(beta) if abs(x) < 1 else 0.0
            row.append(s * w)
        n = sum(row)
        q = [round(v / n * 16384) for v in row]
        q[q.index(max(q))] += 16384 - sum(q)        # each phase sums to one exactly: no DC ripple
        fir.append(q)
    L += ["/* the output resampler: tap k of phase p weighs native frame (i - 7 + k) for the output at i + p/256 */",
          f"static const int16_t ESQ_FIR[{FIR_PHASES}][{FIR_TAPS}] = {{"]
    for q in fir:
        L.append("    {" + ", ".join(str(v) for v in q) + "},")
    L += ["};", "", "#endif", ""]
    (ROOT / "engine/esq_tables.h").write_text("\n".join(L))
    print("gen_tables: engine/esq_tables.h")


if __name__ == "__main__":
    main()
